<script setup lang="ts">import {ref} from 'vue';import {ArrowUp,ArrowDown,Copy} from 'lucide-vue-next';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Field from '@/components/zs/Field.vue';import ZButton from '@/components/zs/ZButton.vue';import {showToast} from '@/composables/useToast';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Lead Capture Forms','Configure embeddable lead capture forms.');function notify(message:string){showToast('Form saved',message)}async function copyEmbed(){await navigator.clipboard.writeText('<scr'+'ipt src=\"https://app.zavsync.com/forms/FORM_ID.js\"></scr'+'ipt>');showToast('Embed code copied','Replace FORM_ID when the hosted form endpoint is available.','info')}const name=ref('Request a ZavSync demo');const fields=ref([{name:'First name',enabled:true,required:true},{name:'Last name',enabled:true,required:true},{name:'Work email',enabled:true,required:true},{name:'Company',enabled:true,required:true},{name:'Phone',enabled:true,required:false},{name:'Job title',enabled:true,required:false},{name:'Website',enabled:false,required:false},{name:'Message',enabled:true,required:false}]);function move(i:number,d:number){const n=i+d;if(n<0||n>=fields.value.length)return;const copy=[...fields.value];const [x]=copy.splice(i,1);if(x)copy.splice(n,0,x);fields.value=copy}</script>
<template><AppShell><PageHeader title="Capture Form Builder" description="Configure fields and preview the future embedded experience"><template #actions><ZButton @click="notify('Form configuration saved in preview mode.')">Save form</ZButton></template></PageHeader><div class="grid gap-3 xl:grid-cols-2"><Panel title="Form configuration" body-class="p-4"><Field v-model="name" label="Form name"/><div class="mt-4 divide-y divide-line"><div v-for="(field,i) in fields" :key="field.name" class="flex items-center gap-3 py-3"><input v-model="field.enabled" type="checkbox"/><span class="flex-1 text-sm text-content">{{field.name}}</span><label class="text-xs text-content-muted"><input v-model="field.required" type="checkbox" :disabled="!field.enabled"/> Required</label><button type="button" aria-label="Move up" class="text-content-muted" @click="move(i,-1)"><ArrowUp class="size-3.5"/></button><button type="button" aria-label="Move down" class="text-content-muted" @click="move(i,1)"><ArrowDown class="size-3.5"/></button></div></div></Panel><div class="space-y-3"><Panel title="Live preview" body-class="p-5"><h2 class="text-lg font-semibold text-content">{{name}}</h2><form class="mt-5 grid gap-3 sm:grid-cols-2" @submit.prevent><label v-for="f in fields.filter(x=>x.enabled)" :key="f.name" :class="f.name==='Message'?'sm:col-span-2':''"><span class="label-caps">{{f.name}}{{f.required?' *':''}}</span><textarea v-if="f.name==='Message'" class="field mt-1.5 min-h-20"></textarea><input v-else class="field mt-1.5" :required="f.required"/></label><ZButton class="sm:col-span-2">Submit</ZButton></form></Panel><Panel title="Embed code" description="Placeholder for the future hosted form endpoint" body-class="p-4"><code class="block overflow-x-auto rounded-md bg-surface-sunken p-3 text-xs text-content-secondary">&lt;script src=&quot;https://app.zavsync.com/forms/FORM_ID.js&quot;&gt;&lt;/script&gt;</code><ZButton variant="outline" class="mt-3" @click="copyEmbed()"><Copy class="size-3.5"/>Copy placeholder</ZButton></Panel></div></div></AppShell></template>
